"""Compare six builder runs. Every scale is diagnostic, never an enclosure."""
import argparse
import json
from pathlib import Path
import numpy as np
import scipy.linalg as sla


def whiten(M, L):
    B = sla.solve_triangular(L, M, lower=True)
    return sla.solve_triangular(L, B.T, lower=True).T


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('output_dir', type=Path)
    ap.add_argument('tag')
    ap.add_argument('report', type=Path)
    args = ap.parse_args()
    rows = []
    for K in (36, 48):
        stems = {mode: args.output_dir / f'window_derivative_K{K}{args.tag}_{mode}' for mode in ('base', 'h', 'xi')}
        matrices = {mode: np.load(str(stem) + '_matrices.npz') for mode, stem in stems.items()}
        margins = {mode: json.loads(Path(str(stem) + '_one_direction.json').read_text()) for mode, stem in stems.items()}
        for a in ('0.70', '0.75', '0.80'):
            base = matrices['base']
            L = sla.cholesky(base[f'{a}_G'], lower=True)
            gauges = {}
            for mode in ('h', 'xi'):
                for name in ('Q', 'G'):
                    gauges[f'E_{name}_{mode}'] = float(np.linalg.norm(whiten(matrices[mode][f'{a}_{name}'] - base[f'{a}_{name}'], L), 2))
            eb = max(gauges['E_Q_h'], gauges['E_Q_xi'])
            eg = max(gauges['E_G_h'], gauges['E_G_xi'])
            for span in ('span_g0-4', 'span_g0-8', 'span_g0-12'):
                row = dict(a=float(a), K=K, span=span, **gauges, E_builder_diagnostic=eb, E_gram_diagnostic=eg)
                problems = []
                for mode in ('base', 'h', 'xi'):
                    result = margins[mode][a]
                    d = result['dirs'][span]
                    row[mode] = dict(lam1=result['lam1'], **d)
                    if d['local_status'] == 'UNRESOLVED':
                        problems.append(mode + ':floating_or_solve_unresolved')
                    if result['lam1'] <= max(d['q_diagnostic_scale'], eb):
                        problems.append(mode + ':lambda_below_builder_or_floating_scale')
                if not np.isfinite(eg) or eg >= 1e-3:
                    problems.append('gram_gauge_exceeds_1e-3')
                row['status'] = 'UNRESOLVED' if problems else 'RESOLVED_DIAGNOSTIC_ONLY'
                row['reasons'] = problems
                rows.append(row)
    report = dict(authority='DIAGNOSTIC_NEVER_A_PROOF', note='Individual h and XI gauges are not a joint error bound. Special-function, theta derivative/projection, quadrature and infinite-tail errors are not enclosed.', rows=rows)
    args.report.write_text(json.dumps(report, indent=2) + '\n')
    print('K a span raw_ratio floating_scale q_scale E_Q_h E_Q_xi status')
    for row in rows:
        d = row['base']
        print(row['K'], row['a'], row['span'], d['q_over_lam1'], d['floating_scale'], d['q_diagnostic_scale'], row['E_Q_h'], row['E_Q_xi'], row['status'])


if __name__ == '__main__':
    main()
